// Lê o /status do serviço no Render e decide se vale acordar alguém.
//
// Avisa quando: o job não concluiu, alguma sucursal deu erro, a contagem
// desabou (fonte fora do ar costuma parecer "imóvel sumiu") ou estourou a cota.
// Silêncio quer dizer que os três feeds subiram com volume normal.

// Referências medidas em 07/09/2026. Atualize se o estoque mudar de patamar.
const REFERENCIA = { ville: 2671, homemark: 2186, alcance: 444 };
const PISO = 0.6; // abaixo de 60% da referência é suspeito

const j = $input.first().json || {};
const linhas = [];
const problemas = [];

if (!j.estado || (j.estado !== 'concluido' && j.estado !== 'concluido_com_erro')) {
  problemas.push('O serviço não terminou a geração (estado: ' + (j.estado || 'desconhecido') + ').');
}

for (const s of (j.sucursais || [])) {
  const nome = s.sucursal;
  if (s.estado !== 'ok') {
    problemas.push(nome + ': ' + (s.erro || 'falhou'));
    linhas.push('• ' + nome + ': ERRO');
    continue;
  }
  const ref = REFERENCIA[nome] || 0;
  const alerta = [];
  if (ref && s.total < Math.round(ref * PISO)) {
    alerta.push('queda de volume (esperado ~' + ref + ')');
  }
  if (s.livres < 0) {
    alerta.push('excede a cota em ' + (-s.livres));
  }
  if (alerta.length) problemas.push(nome + ': ' + alerta.join('; '));
  linhas.push('• ' + nome + ': ' + s.total + ' imóveis, ' + s.mb + ' MB, ' +
              s.livres + ' vagas livres' + (alerta.length ? '  ⚠ ' + alerta.join('; ') : ''));
}

if (!(j.sucursais || []).length) problemas.push('Nenhuma sucursal foi processada.');

const cabecalho = problemas.length
  ? '⚠️ Feed ImovelWeb — atenção'
  : '✅ Feed ImovelWeb atualizado';

const mensagem = [cabecalho, '']
  .concat(linhas)
  .concat(problemas.length ? ['', 'Problemas:'].concat(problemas.map(p => '– ' + p)) : [])
  .join('\n');

return [{ json: { avisar: problemas.length > 0, mensagem, problemas, estado: j.estado || null, job_id: j.job_id || null } }];
